'use client';

import React from 'react';
import { useChatContext } from './chat-context';
import type { ChatMessage as ChatMessageType } from '@/lib/types';
import { Card } from '@/components/ui/card';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Bot,
  User,
  Volume2,
  FileText,
  Image as ImageIcon,
  Download,
  Play,
  Pause,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { format } from 'date-fns';
import { API_BASE_URL } from '@/lib/api-config';

interface MessageBubbleProps {
  message: ChatMessageType;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const isUser = message.role === 'user';
  const [isPlaying, setIsPlaying] = React.useState(false);
  const audioRef = React.useRef<HTMLAudioElement>(null);

  const handlePlayAudio = () => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
        setIsPlaying(false);
      } else {
        audioRef.current.play();
        setIsPlaying(true);
      }
    }
  };

  const getFileIcon = (fileType: string) => {
    if (fileType.startsWith('image/')) return <ImageIcon className="h-4 w-4" />;
    return <FileText className="h-4 w-4" />;
  };

  const getFileName = (url: string) => {
    return url.split('/').pop() || 'file';
  };

  return (
    <div className={cn('flex gap-3 mb-6', isUser && 'flex-row-reverse')}>
      <Avatar className={cn('h-8 w-8', !isUser && 'bg-primary')}>
        <AvatarFallback>
          {isUser ? <User className="h-4 w-4" /> : <Bot className="h-4 w-4" />}
        </AvatarFallback>
      </Avatar>

      <div className={cn('flex flex-col gap-2 max-w-[70%]')}>
        <Card
          className={cn(
            'p-4',
            isUser
              ? 'bg-primary text-primary-foreground'
              : 'bg-muted'
          )}
        >
          {/* Voice message */}
          {message.messageType === 'voice' && message.audioUrl && (
            <div className="mb-3">
              <div className="flex items-center gap-2 mb-2">
                <Volume2 className="h-4 w-4" />
                <Badge variant="secondary" className="text-xs">
                  Voice Message
                </Badge>
              </div>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="icon"
                  onClick={handlePlayAudio}
                  className="h-8 w-8"
                >
                  {isPlaying ? (
                    <Pause className="h-4 w-4" />
                  ) : (
                    <Play className="h-4 w-4" />
                  )}
                </Button>
                <audio
                  ref={audioRef}
                  src={`${API_BASE_URL}${message.audioUrl}`}
                  onEnded={() => setIsPlaying(false)}
                />
                {message.audioDuration && (
                  <span className="text-xs opacity-70">
                    {Math.floor(message.audioDuration / 60)}:
                    {String(message.audioDuration % 60).padStart(2, '0')}
                  </span>
                )}
              </div>
              {message.transcription && (
                <p className="text-xs opacity-70 mt-2 italic">
                  "{message.transcription}"
                </p>
              )}
            </div>
          )}

          {/* Message content */}
          <div className="prose prose-sm dark:prose-invert max-w-none">
            <p className="whitespace-pre-wrap wrap-break-word">{message.content}</p>
          </div>

          {/* Attachments */}
          {message.attachments && message.attachments.length > 0 && (
            <div className="mt-3 space-y-2">
              {message.attachments.map((attachment) => (
                <div
                  key={attachment.id}
                  className="flex items-center gap-2 p-2 rounded bg-background/10"
                >
                  {getFileIcon(attachment.fileType)}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium truncate">
                      {attachment.fileName}
                    </p>
                    <p className="text-xs opacity-70">
                      {(attachment.fileSize / 1024).toFixed(1)} KB
                    </p>
                  </div>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8"
                    asChild
                  >
                    <a
                      href={`${API_BASE_URL}${attachment.fileUrl}`}
                      download
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      <Download className="h-4 w-4" />
                    </a>
                  </Button>
                </div>
              ))}
            </div>
          )}
        </Card>

        <div className={cn('flex items-center gap-2 text-xs text-muted-foreground px-1')}>
          <span>{format(new Date(message.createdAt), 'HH:mm')}</span>
          {message.tokens && (
            <Badge variant="outline" className="text-xs">
              {message.tokens} tokens
            </Badge>
          )}
        </div>
      </div>
    </div>
  );
};
