'use client';

import React, { createContext, useContext, useState, useCallback } from 'react';
import type { MedicalChat, ChatMessage } from '@/lib/types';
import * as medicalChatApi from '@/lib/api/medical-chat';
import { toast } from 'sonner';

interface ChatContextType {
  chats: MedicalChat[];
  currentChat: MedicalChat | null;
  loading: boolean;
  sending: boolean;
  loadChats: () => Promise<void>;
  createNewChat: (firstMessage?: string) => Promise<MedicalChat | null>;
  selectChat: (chatId: string) => Promise<void>;
  sendMessage: (chatId: string, message: string) => Promise<void>;
  sendVoice: (chatId: string, audioBlob: Blob) => Promise<void>;
  uploadFile: (chatId: string, messageId: string, file: File) => Promise<void>;
  archiveChat: (chatId: string) => Promise<void>;
  deleteChat: (chatId: string) => Promise<void>;
  refreshCurrentChat: () => Promise<void>;
}

const ChatContext = createContext<ChatContextType | undefined>(undefined);

export const useChatContext = () => {
  const context = useContext(ChatContext);
  if (!context) {
    throw new Error('useChatContext must be used within ChatProvider');
  }
  return context;
};

export const ChatProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const [chats, setChats] = useState<MedicalChat[]>([]);
  const [currentChat, setCurrentChat] = useState<MedicalChat | null>(null);
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);

  const loadChats = useCallback(async () => {
    try {
      setLoading(true);
      const response = await medicalChatApi.getAllChats({
        status: 'active',
        limit: 50,
      });
      setChats(response.data.chats);
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Failed to load chats');
      console.error('Error loading chats:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  const createNewChat = useCallback(
    async (firstMessage?: string): Promise<MedicalChat | null> => {
      try {
        setLoading(true);
        const response = await medicalChatApi.createChat(firstMessage);
        const newChat = response.data;
        setChats((prev) => [newChat, ...prev]);
        setCurrentChat(newChat);
        toast.success('New chat created');
        return newChat;
      } catch (error: any) {
        toast.error(error.response?.data?.message || 'Failed to create chat');
        console.error('Error creating chat:', error);
        return null;
      } finally {
        setLoading(false);
      }
    },
    []
  );

  const selectChat = useCallback(async (chatId: string) => {
    try {
      setLoading(true);
      const response = await medicalChatApi.getChatById(chatId);
      setCurrentChat(response.data);
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Failed to load chat');
      console.error('Error loading chat:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  const refreshCurrentChat = useCallback(async () => {
    if (!currentChat) return;
    try {
      const response = await medicalChatApi.getChatById(currentChat.id);
      setCurrentChat(response.data);
    } catch (error) {
      console.error('Error refreshing chat:', error);
    }
  }, [currentChat]);

  const sendMessage = useCallback(
    async (chatId: string, message: string) => {
      try {
        setSending(true);
        const response = await medicalChatApi.sendTextMessage(chatId, message);

        // Update current chat with new messages
        if (currentChat?.id === chatId) {
          setCurrentChat((prev) => {
            if (!prev) return prev;
            return {
              ...prev,
              messages: [
                ...prev.messages,
                response.data.userMessage,
                response.data.assistantMessage,
              ],
            };
          });
        }

        // Update chat list
        await loadChats();
      } catch (error: any) {
        toast.error(error.response?.data?.message || 'Failed to send message');
        throw error;
      } finally {
        setSending(false);
      }
    },
    [currentChat, loadChats]
  );

  const sendVoice = useCallback(
    async (chatId: string, audioBlob: Blob) => {
      try {
        setSending(true);
        const response = await medicalChatApi.sendVoiceMessage(
          chatId,
          audioBlob
        );

        // Update current chat with new messages
        if (currentChat?.id === chatId) {
          setCurrentChat((prev) => {
            if (!prev) return prev;
            return {
              ...prev,
              messages: [
                ...prev.messages,
                response.data.userMessage,
                response.data.assistantMessage,
              ],
            };
          });
        }

        toast.success(
          `Voice message sent: "${response.data.transcription.substring(0, 30)}..."`
        );
        await loadChats();
      } catch (error: any) {
        toast.error(
          error.response?.data?.message || 'Failed to send voice message'
        );
        throw error;
      } finally {
        setSending(false);
      }
    },
    [currentChat, loadChats]
  );

  const uploadFile = useCallback(
    async (chatId: string, messageId: string, file: File) => {
      try {
        await medicalChatApi.uploadAttachment(chatId, messageId, file);
        toast.success(`File uploaded: ${file.name}`);
        await refreshCurrentChat();
      } catch (error: any) {
        toast.error(error.response?.data?.message || 'Failed to upload file');
        throw error;
      }
    },
    [refreshCurrentChat]
  );

  const archiveChat = useCallback(
    async (chatId: string) => {
      try {
        await medicalChatApi.updateChatStatus(chatId, 'archived');
        setChats((prev) => prev.filter((chat) => chat.id !== chatId));
        if (currentChat?.id === chatId) {
          setCurrentChat(null);
        }
        toast.success('Chat archived');
      } catch (error: any) {
        toast.error(error.response?.data?.message || 'Failed to archive chat');
      }
    },
    [currentChat]
  );

  const deleteChat = useCallback(
    async (chatId: string) => {
      try {
        await medicalChatApi.deleteChat(chatId);
        setChats((prev) => prev.filter((chat) => chat.id !== chatId));
        if (currentChat?.id === chatId) {
          setCurrentChat(null);
        }
        toast.success('Chat deleted');
      } catch (error: any) {
        toast.error(error.response?.data?.message || 'Failed to delete chat');
      }
    },
    [currentChat]
  );

  const value: ChatContextType = {
    chats,
    currentChat,
    loading,
    sending,
    loadChats,
    createNewChat,
    selectChat,
    sendMessage,
    sendVoice,
    uploadFile,
    archiveChat,
    deleteChat,
    refreshCurrentChat,
  };

  return <ChatContext.Provider value={value}>{children}</ChatContext.Provider>;
};
