'use client';

import React from 'react';
import { useChatContext } from './chat-context';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Skeleton } from '@/components/ui/skeleton';
import {
  MessageSquarePlus,
  MessageSquare,
  Archive,
  Trash2,
  MoreVertical,
} from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { formatDistanceToNow } from 'date-fns';
import { cn } from '@/lib/utils';

export const ChatList: React.FC = () => {
  const {
    chats,
    currentChat,
    loading,
    createNewChat,
    selectChat,
    archiveChat,
    deleteChat,
  } = useChatContext();

  const handleNewChat = async () => {
    await createNewChat();
  };

  const handleArchive = async (chatId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Archive this chat?')) {
      await archiveChat(chatId);
    }
  };

  const handleDelete = async (chatId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Delete this chat permanently?')) {
      await deleteChat(chatId);
    }
  };

  return (
    <div className="flex flex-col h-full border-r bg-muted/20">
      <div className="p-4 border-b">
        <Button
          onClick={handleNewChat}
          className="w-full"
          size="lg"
          disabled={loading}
        >
          <MessageSquarePlus className="mr-2 h-5 w-5" />
          New Chat
        </Button>
      </div>

      <ScrollArea className="flex-1">
        <div className="p-2 space-y-2">
          {loading && chats.length === 0 ? (
            // Loading skeletons
            Array.from({ length: 5 }).map((_, i) => (
              <Card key={i} className="p-3">
                <Skeleton className="h-4 w-3/4 mb-2" />
                <Skeleton className="h-3 w-1/2" />
              </Card>
            ))
          ) : chats.length === 0 ? (
            <div className="text-center py-12 px-4">
              <MessageSquare className="mx-auto h-12 w-12 text-muted-foreground mb-3" />
              <p className="text-sm text-muted-foreground">
                No chats yet. Start a new conversation!
              </p>
            </div>
          ) : (
            chats.map((chat) => (
              <Card
                key={chat.id}
                className={cn(
                  'p-3 cursor-pointer transition-colors hover:bg-accent',
                  currentChat?.id === chat.id && 'bg-accent border-primary'
                )}
                onClick={() => selectChat(chat.id)}
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    <h3 className="font-medium text-sm truncate mb-1">
                      {chat.title}
                    </h3>
                    {chat.messages.length > 0 && (
                      <p className="text-xs text-muted-foreground truncate">
                        {chat.messages[chat.messages.length - 1].role ===
                        'user'
                          ? 'You: '
                          : 'AI: '}
                        {chat.messages[chat.messages.length - 1].content}
                      </p>
                    )}
                    <p className="text-xs text-muted-foreground mt-1">
                      {formatDistanceToNow(new Date(chat.updatedAt), {
                        addSuffix: true,
                      })}
                    </p>
                  </div>

                  <DropdownMenu>
                    <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                      <Button variant="ghost" size="icon" className="h-8 w-8">
                        <MoreVertical className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem
                        onClick={(e) => handleArchive(chat.id, e)}
                      >
                        <Archive className="mr-2 h-4 w-4" />
                        Archive
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        onClick={(e) => handleDelete(chat.id, e)}
                        className="text-destructive"
                      >
                        <Trash2 className="mr-2 h-4 w-4" />
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </Card>
            ))
          )}
        </div>
      </ScrollArea>
    </div>
  );
};
