'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useChatContext } from './chat-context';
import { MessageBubble } from './message-bubble';
import { VoiceRecorder } from './voice-recorder';
import { FileUpload } from './file-upload';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Card } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { Send, Bot, AlertCircle } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';

export const ChatWindow: React.FC = () => {
  const { currentChat, loading, sending, sendMessage, sendVoice, uploadFile } =
    useChatContext();
  const [message, setMessage] = useState('');
  const scrollAreaRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    if (scrollAreaRef.current) {
      const scrollElement = scrollAreaRef.current.querySelector(
        '[data-radix-scroll-area-viewport]'
      );
      if (scrollElement) {
        scrollElement.scrollTop = scrollElement.scrollHeight;
      }
    }
  }, [currentChat?.messages]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!message.trim() || !currentChat || sending) return;

    const messageText = message.trim();
    setMessage('');
    
    try {
      await sendMessage(currentChat.id, messageText);
    } catch (error) {
      // Error is already handled in context
      setMessage(messageText); // Restore message on error
    }
  };

  const handleVoiceRecording = async (audioBlob: Blob) => {
    if (!currentChat || sending) return;
    
    try {
      await sendVoice(currentChat.id, audioBlob);
    } catch (error) {
      // Error is already handled in context
    }
  };

  const handleFileUpload = async (file: File) => {
    if (!currentChat || !currentChat.messages.length) {
      alert('Please send a message first before uploading files');
      return;
    }

    // Get the last user message to attach file to
    const lastUserMessage = [...currentChat.messages]
      .reverse()
      .find((msg) => msg.role === 'user');

    if (!lastUserMessage) {
      alert('No message to attach file to');
      return;
    }

    try {
      await uploadFile(currentChat.id, lastUserMessage.id, file);
    } catch (error) {
      // Error is already handled in context
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage(e);
    }
  };

  if (!currentChat) {
    return (
      <div className="flex items-center justify-center h-full bg-muted/20">
        <div className="text-center space-y-4">
          <Bot className="mx-auto h-16 w-16 text-muted-foreground" />
          <div>
            <h3 className="text-lg font-semibold mb-2">AI Medical Assistant</h3>
            <p className="text-sm text-muted-foreground max-w-md">
              Select a chat or start a new conversation to get medical guidance and support.
            </p>
          </div>
          <Alert className="max-w-md mx-auto">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="text-xs">
              This AI assistant provides general health information only and is not a replacement for professional medical care.
            </AlertDescription>
          </Alert>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="p-4 border-b bg-background">
        <div className="flex items-center gap-3">
          <div className="h-10 w-10 rounded-full bg-primary flex items-center justify-center">
            <Bot className="h-5 w-5 text-primary-foreground" />
          </div>
          <div>
            <h2 className="font-semibold">AI Medical Assistant</h2>
            <p className="text-xs text-muted-foreground">
              Powered by GPT-4 • Always online
            </p>
          </div>
        </div>
      </div>

      {/* Messages */}
      <ScrollArea ref={scrollAreaRef} className="flex-1 p-4">
        {loading && currentChat.messages.length === 0 ? (
          <div className="space-y-4">
            {Array.from({ length: 3 }).map((_, i) => (
              <div key={i} className="flex gap-3">
                <Skeleton className="h-8 w-8 rounded-full" />
                <div className="space-y-2 flex-1">
                  <Skeleton className="h-4 w-3/4" />
                  <Skeleton className="h-4 w-1/2" />
                </div>
              </div>
            ))}
          </div>
        ) : currentChat.messages.length === 0 ? (
          <div className="text-center py-12">
            <Bot className="mx-auto h-12 w-12 text-muted-foreground mb-3" />
            <p className="text-sm text-muted-foreground">
              Start the conversation by sending a message
            </p>
          </div>
        ) : (
          <div className="space-y-1">
            {currentChat.messages.map((msg) => (
              <MessageBubble key={msg.id} message={msg} />
            ))}
            {sending && (
              <div className="flex gap-3 mb-6">
                <div className="h-8 w-8 rounded-full bg-primary flex items-center justify-center">
                  <Bot className="h-4 w-4 text-primary-foreground" />
                </div>
                <Card className="p-4 bg-muted">
                  <div className="flex gap-1">
                    <div className="h-2 w-2 bg-foreground/40 rounded-full animate-bounce" />
                    <div className="h-2 w-2 bg-foreground/40 rounded-full animate-bounce [animation-delay:0.2s]" />
                    <div className="h-2 w-2 bg-foreground/40 rounded-full animate-bounce [animation-delay:0.4s]" />
                  </div>
                </Card>
              </div>
            )}
          </div>
        )}
      </ScrollArea>

      {/* Input Area */}
      <div className="p-4 border-t bg-background">
        <form onSubmit={handleSendMessage} className="flex gap-2">
          <VoiceRecorder
            onRecordingComplete={handleVoiceRecording}
            disabled={sending}
          />
          <FileUpload
            onFileSelect={handleFileUpload}
            disabled={sending}
          />
          <div className="flex-1">
            <Textarea
              ref={textareaRef}
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Type your medical question... (Shift+Enter for new line)"
              disabled={sending}
              className="min-h-16 max-h-[200px] resize-none"
              maxLength={2000}
            />
          </div>
          <Button
            type="submit"
            size="icon"
            disabled={!message.trim() || sending}
            className="h-16 w-16 rounded-full"
          >
            <Send className="h-5 w-5" />
          </Button>
        </form>
        <p className="text-xs text-muted-foreground mt-2 text-center">
          {message.length}/2000 characters • Not a replacement for professional medical care
        </p>
      </div>
    </div>
  );
};
